"use client"

import { useEffect, useRef, useState } from "react"
import { ArrowDown, ArrowUp } from "lucide-react"
import { Alert } from "@atlas/ui-web/compositions/Alert/Alert"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Card, CardContent, CardHeader, CardTitle } from "@atlas/ui-web/compositions/Card/Card"
import {
  Chart,
  ChartBar,
  ChartContent,
  ChartDescription,
  ChartHeader,
  ChartTitle,
} from "@atlas/ui-web/compositions/Chart/Chart"
import {
  ListItem,
  ListItemActions,
  ListItemContent,
  ListItemDescription,
  ListItemTitle,
} from "@atlas/ui-web/compositions/ListItem/ListItem"
import { Skeleton } from "@atlas/ui-web/primitives/Skeleton/Skeleton"
import { TabsList, TabsRoot, TabsTrigger } from "@atlas/ui-web/patterns/Tabs/Tabs"
import { FlowShell } from "../_shared/FlowShell"
import {
  SUMMARIES,
  TRANSACTIONS,
  WEEK_SPENDING,
  formatMoney,
  formatSigned,
  type Summary,
} from "./data"

type View = "loaded" | "loading" | "failed"

const RETRY_DELAY_MS = 900

const column = { display: "flex", flexDirection: "column" } as const
const mutedText = {
  color: "var(--atlas-foreground-muted)",
  fontSize: "var(--atlas-text-body-sm)",
} as const

function SummaryTile({ item }: { item: Summary }) {
  const up = item.change > 0
  const good = up === item.upIsGood
  return (
    <Card variant="outlined" size="sm">
      <CardContent>
        <div style={{ ...column, gap: "var(--atlas-spacing-1)" }}>
          <span style={mutedText}>{item.label}</span>
          <span
            style={{
              fontSize: "var(--atlas-font-size-xl)",
              fontWeight: "var(--atlas-font-weight-semibold)",
              color: "var(--atlas-foreground)",
            }}
          >
            {formatMoney(item.value)}
          </span>
          <div>
            <Badge
              size="sm"
              variant={good ? "success" : "danger"}
              leadingIcon={up ? <ArrowUp size={12} aria-hidden /> : <ArrowDown size={12} aria-hidden />}
            >
              {`${up ? "Up" : "Down"} ${Math.abs(item.change)}%`}
            </Badge>
          </div>
          <span style={{ ...mutedText, fontSize: "var(--atlas-text-caption)" }}>since last month</span>
        </div>
      </CardContent>
    </Card>
  )
}

function SummaryGrid({ loading }: { loading: boolean }) {
  return (
    <div
      aria-busy={loading}
      style={{
        display: "grid",
        gridTemplateColumns: "repeat(2, minmax(0, 1fr))",
        gap: "var(--atlas-spacing-3)",
      }}
    >
      {loading
        ? SUMMARIES.map((s) => (
            <Card key={s.key} variant="outlined" size="sm">
              <CardContent>
                <div style={{ ...column, gap: "var(--atlas-spacing-2)" }}>
                  <Skeleton style={{ width: "50%" }} />
                  <Skeleton style={{ height: "var(--atlas-spacing-6)" }} />
                  <Skeleton style={{ width: "70%" }} />
                </div>
              </CardContent>
            </Card>
          ))
        : SUMMARIES.map((s) => <SummaryTile key={s.key} item={s} />)}
    </div>
  )
}

function SpendingChart({ loading }: { loading: boolean }) {
  return (
    <Chart state={loading ? "loading" : "default"}>
      <ChartHeader>
        <ChartTitle>Spending</ChartTitle>
        <ChartDescription>Daily spending over the last 7 days</ChartDescription>
      </ChartHeader>
      <ChartContent loadingLabel="Loading spending chart">
        <ChartBar
          aria-label="Bar chart of daily spending in dollars for the last 7 days"
          data={WEEK_SPENDING}
          xKey="day"
          dataKey="spent"
          label="Spent"
        />
      </ChartContent>
    </Chart>
  )
}

function RecentActivity({ loading }: { loading: boolean }) {
  return (
    <Card variant="outlined">
      <CardHeader>
        <CardTitle as="h2">Recent activity</CardTitle>
      </CardHeader>
      <CardContent>
        <ul
          aria-busy={loading}
          style={{ ...column, listStyle: "none", margin: 0, padding: 0, gap: "var(--atlas-spacing-2)" }}
        >
          {loading
            ? TRANSACTIONS.map((t) => (
                <li key={t.id}>
                  <div style={{ ...column, gap: "var(--atlas-spacing-1_5)", paddingBlock: "var(--atlas-spacing-2)" }}>
                    <Skeleton style={{ width: "55%" }} />
                    <Skeleton style={{ width: "35%" }} />
                  </div>
                </li>
              ))
            : TRANSACTIONS.map((t) => (
                <ListItem key={t.id} as="li" size="sm">
                  <ListItemContent>
                    <ListItemTitle>{t.name}</ListItemTitle>
                    <ListItemDescription>{`${t.category} · ${t.date}`}</ListItemDescription>
                  </ListItemContent>
                  <ListItemActions>
                    <span
                      style={{
                        fontWeight: "var(--atlas-font-weight-medium)",
                        color: t.amount > 0 ? "var(--atlas-success)" : "var(--atlas-foreground)",
                      }}
                    >
                      {formatSigned(t.amount)}
                    </span>
                  </ListItemActions>
                </ListItem>
              ))}
        </ul>
      </CardContent>
    </Card>
  )
}

export default function DashboardSummaryPage() {
  const [view, setView] = useState<View>("loaded")
  const [retrying, setRetrying] = useState(false)
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null)

  useEffect(() => () => {
    if (timer.current) clearTimeout(timer.current)
  }, [])

  const choose = (next: string) => {
    if (timer.current) clearTimeout(timer.current)
    setRetrying(false)
    setView(next as View)
  }

  // The mock request always succeeds on retry, so reviewers can see the recovery.
  const retry = () => {
    setRetrying(true)
    timer.current = setTimeout(() => {
      setRetrying(false)
      setView("loaded")
    }, RETRY_DELAY_MS)
  }

  const loading = view === "loading"

  return (
    <FlowShell
      title="Dashboard summary"
      step={0}
      totalSteps={1}
      showProgress={false}
      onReset={() => choose("loaded")}
      phoneBackground="var(--atlas-background)"
    >
      <div
        style={{
          ...column,
          gap: "var(--atlas-spacing-4)",
          paddingInline: "var(--atlas-spacing-4)",
          paddingBlockEnd: "var(--atlas-spacing-6)",
        }}
      >
        <TabsRoot variant="segmented" size="sm" value={view} onValueChange={choose}>
          <TabsList aria-label="Review state">
            <TabsTrigger value="loaded">Loaded</TabsTrigger>
            <TabsTrigger value="loading">Loading</TabsTrigger>
            <TabsTrigger value="failed">Failed</TabsTrigger>
          </TabsList>
        </TabsRoot>

        <header style={{ ...column, gap: "var(--atlas-spacing-1)" }}>
          <h1
            style={{
              margin: 0,
              fontSize: "var(--atlas-text-h1)",
              fontWeight: "var(--atlas-font-weight-bold)",
              lineHeight: "var(--atlas-line-height-tight)",
              color: "var(--atlas-foreground)",
            }}
          >
            Dashboard
          </h1>
          <p style={{ ...mutedText, margin: 0 }}>Good morning, Alex. Here&apos;s your month so far.</p>
        </header>

        {view === "failed" ? (
          <Alert
            variant="danger"
            title="We couldn't load your dashboard"
            description="Your account is safe and nothing has changed. Check your connection and try again."
            actions={
              <Button size="sm" variant="primary" loading={retrying} onClick={retry}>
                Try again
              </Button>
            }
          />
        ) : (
          <>
            <SummaryGrid loading={loading} />
            <SpendingChart loading={loading} />
            <RecentActivity loading={loading} />
          </>
        )}
      </div>
    </FlowShell>
  )
}

