        }}
      >
        <TabsRoot variant="segmented" size="sm" value={view} onValueChange={choose}>
          <TabsList aria-label="Review state">
            <TabsTrigger value="loaded">Loaded</TabsTrigger>
            <TabsTrigger value="loading">Loading</TabsTrigger>
            <TabsTrigger value="failed">Failed</TabsTrigger>
          </TabsList>
        </TabsRoot>

        <header style={{ ...column, gap: "var(--atlas-spacing-1)" }}>
          <h1
            style={{
              margin: 0,
              fontSize: "var(--atlas-text-h1)",
              fontWeight: "var(--atlas-font-weight-bold)",
              lineHeight: "var(--atlas-line-height-tight)",
              color: "var(--atlas-foreground)",
            }}
          >
            Dashboard
          </h1>
          <p style={{ ...mutedText, margin: 0 }}>Good morning, Alex. Here&apos;s your month so far.</p>
        </header>

        {view === "failed" ? (
          <Alert
            variant="danger"
            title="We couldn't load your dashboard"
